	start := 0
	for i := 0; i <= len(path); i++ {
		if i < len(path) && path[i] != '.' {
			continue
		}

		segment := path[start:i]
		start = i + 1

		at = at.Get(segment)
		if at.IsUndefined() || at.IsNull() {
			return js.Undefined(), errors.New(path + " is not there: " + segment + " is missing")
		}
	}

	return at, nil
